const order = ['EUR','GBP','AUD','NZD','USD','CAD','CHF','JPY'];
const out = [];
for (let i = 0; i < order.length; i++) for (let j = i + 1; j < order.length; j++) {
  const base = order[i], quote = order[j];
  out.push({ json: { kind: 'fx', pair: `${base}/${quote}`, base, quote, yahoo: `${base}${quote}=X` } });
}

// Assets — Yahoo symbols (Gold spot চাইলে 'XAUUSD=X' বসাতে পারো)
const assets = [
  { pair: 'Gold',    name: 'Gold',    icon: '🥇', yahoo: 'GC=F',    dec: 2, group: 'METALS', sessions: ['London', 'New York'] },
  { pair: 'Silver',  name: 'Silver',  icon: '🥈', yahoo: 'SI=F',    dec: 3, group: 'METALS', sessions: ['London', 'New York'] },
  { pair: 'Oil',     name: 'WTI Oil', icon: '🛢️', yahoo: 'CL=F',    dec: 2, group: 'OIL',    sessions: ['New York'] },
  { pair: 'Bitcoin', name: 'Bitcoin', icon: '₿',  yahoo: 'BTC-USD', dec: 1, group: 'BTC',    sessions: null }
];
for (const a of assets) out.push({ json: { kind: 'asset', ...a } });
return out;

const cfg = $('Parse Request').first().json;
const pairs = $('Build Pairs1').all();
const r15 = $('Get Yahoo 15m1').all();
const r1h = $('Get Yahoo 1H').all();
const OFF = 21600;
const nowSec = Math.floor(Date.now() / 1000);
const majors = ['USD','EUR','GBP','JPY','AUD','NZD','CAD','CHF'];
const flags = { USD:'🇺🇸', EUR:'🇪🇺', GBP:'🇬🇧', JPY:'🇯🇵', AUD:'🇦🇺', NZD:'🇳🇿', CAD:'🇨🇦', CHF:'🇨🇭' };
const SESS = { 'Asian': ['JPY','AUD','NZD'], 'London': ['EUR','GBP','CHF'], 'New York': ['USD','CAD','EUR','GBP'] };
const sg = v => (v > 0 ? '+' : '') + v;
const sgn = Math.sign;
const avg = a => a.reduce((s, x) => s + x, 0) / a.length;
const r1 = x => Math.round(x * 10) / 10;

function ema(c, p) { if (c.length < p) return null; const k = 2 / (p + 1); let e = c.slice(0, p).reduce((a, b) => a + b, 0) / p; for (let i = p; i < c.length; i++) e = c[i] * k + e * (1 - k); return e; }
function rsiSeries(c, p) { const r = []; let g = 0, l = 0; for (let i = 1; i <= p; i++) { const d = c[i] - c[i - 1]; if (d >= 0) g += d; else l -= d; } g /= p; l /= p; r[p] = l === 0 ? 100 : 100 - 100 / (1 + g / l); for (let i = p + 1; i < c.length; i++) { const d = c[i] - c[i - 1]; g = (g * (p - 1) + (d > 0 ? d : 0)) / p; l = (l * (p - 1) + (d < 0 ? -d : 0)) / p; r[i] = l === 0 ? 100 : 100 - 100 / (1 + g / l); } return r; }
function swings(arr, lb) { const s = Math.max(1, arr.length - lb); const hi = [], lo = []; for (let i = s; i < arr.length - 1; i++) { if (arr[i] > arr[i - 1] && arr[i] > arr[i + 1]) hi.push(i); if (arr[i] < arr[i - 1] && arr[i] < arr[i + 1]) lo.push(i); } return { hi, lo }; }
function parse(j) { const res = j && j.chart && j.chart.result && j.chart.result[0]; const q = res && res.indicators && res.indicators.quote && res.indicators.quote[0]; if (!res || !res.timestamp || !q) return null; const out = []; for (let i = 0; i < res.timestamp.length; i++) { const o = q.open[i], h = q.high[i], l = q.low[i], c = q.close[i]; if (o == null || h == null || l == null || c == null) continue; out.push({ ts: res.timestamp[i], o, h, l, c }); } return out; }
function bucket(c, sec) { const m = new Map(); for (const x of c) { const k = Math.floor((x.ts + OFF) / sec); const b = m.get(k); if (!b) m.set(k, { ts: k * sec - OFF, o: x.o, h: x.h, l: x.l, c: x.c }); else { b.h = Math.max(b.h, x.h); b.l = Math.min(b.l, x.l); b.c = x.c; } } return Array.from(m.values()).sort((a, b) => a.ts - b.ts); }
function closedOnly(c, sec) { const x = c[c.length - 1]; return (x && nowSec < x.ts + sec) ? c.slice(0, -1) : c; }
const trOf = (c, i) => Math.max(c[i].h - c[i].l, Math.abs(c[i].h - c[i - 1].c), Math.abs(c[i].l - c[i - 1].c));
const atrS = c => { const t = []; for (let i = c.length - 14; i < c.length; i++) t.push(trOf(c, i)); return avg(t); };
const nz = (x, a) => (a > 0 ? x / a : 0);

const per = [], skipped = []; let lastTs = 0;
pairs.forEach((pp, idx) => {
  const m = pp.json;
  const { pair, base, quote } = m;
  const a15 = parse(r15[idx] && r15[idx].json);
  const a1 = parse(r1h[idx] && r1h[idx].json);
  if (!a15 || !a1 || !a15.length || !a1.length) { skipped.push(pair); return; }
  const live = a15[a15.length - 1].c;
  const lastCandle = a15[a15.length - 1].ts;
  if (m.kind !== 'asset') lastTs = Math.max(lastTs, lastCandle);
  const c15 = closedOnly(a15, 900);
  const c1 = closedOnly(a1, 3600);
  const c4 = closedOnly(bucket(a1, 14400), 14400);
  if (c15.length < 220 || c1.length < 210 || c4.length < 205) { skipped.push(pair); return; }
  const cl15 = c15.map(x => x.c), cl1 = c1.map(x => x.c), cl4 = c4.map(x => x.c);
  const e4 = ema(cl4, 200), e1 = ema(cl1, 200), e50 = ema(cl15, 50), e20 = ema(cl15, 20);
  const p15 = cl15[cl15.length - 1];
  const n = cl15.length;
  const net = cl15[n - 1] - cl15[n - 25];
  let path = 0; for (let i = n - 24; i < n; i++) path += Math.abs(cl15[i] - cl15[i - 1]);
  const er = path > 0 ? Math.abs(net) / path : 0;
  const trs = []; for (let i = c15.length - 208; i < c15.length; i++) trs.push(trOf(c15, i));
  const act = avg(trs.slice(0, -8)) > 0 ? avg(trs.slice(-8)) / avg(trs.slice(0, -8)) : 1;
  const atr15 = avg(trs.slice(-14));
  const ts4 = nz(cl4[cl4.length - 1] - e4, atrS(c4));
  const ts1 = nz(cl1[cl1.length - 1] - e1, atrS(c1));
  const ts15 = nz(p15 - e50, atr15);
  const cs = cl15.slice(-300);
  const rs = rsiSeries(cs, 14); const rsi = rs[rs.length - 1];
  const { hi, lo } = swings(cs, 60);
  let div = null;
  if (lo.length >= 2) { const i1 = lo[lo.length - 2], i2 = lo[lo.length - 1]; if (cs[i2] < cs[i1] && rs[i2] > rs[i1]) div = 'BULLISH'; }
  if (!div && hi.length >= 2) { const i1 = hi[hi.length - 2], i2 = hi[hi.length - 1]; if (cs[i2] > cs[i1] && rs[i2] < rs[i1]) div = 'BEARISH'; }
  const day = {};
  for (const x of a15) { const d = Math.floor((x.ts + OFF) / 86400); const b = day[d] || (day[d] = { h: -Infinity, l: Infinity, n: 0 }); b.h = Math.max(b.h, x.h); b.l = Math.min(b.l, x.l); b.n++; }
  const todayKey = Math.floor((nowSec + OFF) / 86400);
  const full = Object.keys(day).map(Number).filter(k => k < todayKey && day[k].n >= 60).sort((a, b) => a - b);
  const pdk = full.length ? full[full.length - 1] : null;
  const pdh = pdk !== null ? day[pdk].h : null;
  const pdl = pdk !== null ? day[pdk].l : null;
  const adrDays = full.slice(-14);
  const adr = adrDays.length ? avg(adrDays.map(k => day[k].h - day[k].l)) : null;
  const t = day[todayKey];
  const adrPct = (adr && t) ? Math.round((t.h - t.l) / adr * 100) : null;
  const orC = a15.filter(x => x.ts >= cfg.sessionStartTs && x.ts < cfg.sessionStartTs + 3600);
  const orHave = orC.length >= 4;
  const orHigh = orHave ? Math.max(...orC.map(x => x.h)) : null;
  const orLow = orHave ? Math.min(...orC.map(x => x.l)) : null;
  per.push({ kind: m.kind, name: m.name, icon: m.icon, dec: m.dec, group: m.group, sessions: m.sessions, stale: nowSec - lastCandle > 10800, pair, base, quote, win4: sgn(cl4[cl4.length - 1] - e4), win1: sgn(cl1[cl1.length - 1] - e1), win15: sgn(p15 - e50), ts4, ts1, ts15, live, p15, e20, e50, rsi, er, net, act, atr15, adrPct, pdh, pdl, div, orHave, orHigh, orLow });
});

const s1 = {}, s4 = {}, s15 = {};
majors.forEach(c => { s1[c] = 0; s4[c] = 0; s15[c] = 0; });
for (const p of per) { if (p.kind === 'asset') continue; s1[p.base] += p.win1; s1[p.quote] -= p.win1; s4[p.base] += p.win4; s4[p.quote] -= p.win4; s15[p.base] += p.win15; s15[p.quote] -= p.win15; }

const orReady = cfg.orDone && per.some(p => p.orHave);
const active = SESS[cfg.session] || [];
const closedAssets = [];

const evald = per.filter(p => !cfg.watchlist || cfg.watchlist.includes(p.pair)).filter(p => { if (p.kind === 'asset' && p.stale) { closedAssets.push(p.name); return false; } return true; }).map(p => {
  const isA = p.kind === 'asset';
  const d4 = isA ? r1(p.ts4) : s4[p.base] - s4[p.quote];
  const d1 = isA ? r1(p.ts1) : s1[p.base] - s1[p.quote];
  const d15 = isA ? r1(p.ts15) : s15[p.base] - s15[p.quote];
  const scale = isA ? 3 : 7;
  const v = d1 + d15;
  const bias = v > 0 ? 'BUY' : v < 0 ? 'SELL' : null;
  const dir = bias === 'BUY' ? 1 : bias === 'SELL' ? -1 : 0;
  const cnt = dir === 0 ? 0 : [d4, d1, d15].filter(d => sgn(d) === dir).length;
  const A = cnt === 3 ? 20 : cnt === 2 ? 8 : 0;
  const B = dir === 0 ? 0 : Math.min(Math.abs(d1) / scale, 1) * 8 + Math.min(Math.abs(d15) / scale, 1) * 7;
  const erOk = dir !== 0 && sgn(p.net) === dir;
  const emaOk = dir !== 0 && dir * (p.p15 - p.e50) > 0 && dir * (p.e20 - p.e50) > 0;
  const C = (erOk ? Math.min(p.er / 0.5, 1) * 15 : 0) + (emaOk ? 5 : 0);
  const D = (p.act >= 0.9 && p.act <= 1.8) ? 10 : (p.act >= 0.7 && p.act < 0.9) ? 5 : p.act > 1.8 ? 6 : 0;
  let E;
  if (isA) E = p.sessions === null ? 3 : p.sessions.includes(cfg.session) ? 5 : 2;
  else { const nAct = [p.base, p.quote].filter(c => active.includes(c)).length; E = nAct === 2 ? 5 : nAct === 1 ? 3 : 1; }
  let F = 7, orConfirmed = false, orLive = false;
  if (orReady && dir !== 0 && p.orHave) {
    orConfirmed = bias === 'BUY' ? p.p15 > p.orHigh : p.p15 < p.orLow;
    orLive = bias === 'BUY' ? p.live > p.orHigh : p.live < p.orLow;
    F = orConfirmed ? 15 : orLive ? 7 : 0;
  } else if (orReady) { F = 0; }
  const adrPts = p.adrPct === null ? 2 : p.adrPct < 60 ? 5 : p.adrPct < 90 ? 3 : p.adrPct < 110 ? 1 : 0;
  let obstacle = null, roomATR = null;
  if (bias === 'BUY' && p.pdh !== null && p.pdh > p.live) { obstacle = p.pdh; roomATR = (p.pdh - p.live) / p.atr15; }
  if (bias === 'SELL' && p.pdl !== null && p.pdl < p.live) { obstacle = p.pdl; roomATR = (p.live - p.pdl) / p.atr15; }
  const roomPts = roomATR === null ? 10 : roomATR >= 3 ? 10 : roomATR >= 2 ? 6 : roomATR >= 1.5 ? 3 : 0;
  const cramped = roomATR !== null && roomATR < 1.5;
  const G = adrPts + roomPts;
  const stretched = (bias === 'BUY' && p.rsi >= 75) || (bias === 'SELL' && p.rsi <= 25);
  const divAgainst = !!(p.div && ((bias === 'BUY' && p.div === 'BEARISH') || (bias === 'SELL' && p.div === 'BULLISH')));
  const extended = dir !== 0 && dir * (p.live - p.e50) / p.atr15 > 3.5;
  const pen = (stretched ? 8 : 0) + (divAgainst ? 7 : 0) + (extended ? 6 : 0);
  const score = Math.max(0, Math.min(100, Math.round(A + B + C + D + E + F + G - pen)));
  return { ...p, d4, d1, d15, bias, cnt, A: Math.round(A + B), C: Math.round(C), D, E, F, G, pen, score, orConfirmed, orLive, obstacle, roomATR, cramped, stretched, divAgainst, extended };
});

const isFocus = r => r.bias && r.cnt === 3 && r.score >= 65 && !r.cramped && (orReady ? r.orConfirmed : true);
const keysOf = r => (r.kind === 'asset' ? [r.group] : [r.base, r.quote]);
function pickDiverse(list, n) { const chosen = []; const used = new Set(); for (const c of list) { if (chosen.length >= n) break; const k = keysOf(c); if (!k.some(x => used.has(x))) { chosen.push(c); k.forEach(x => used.add(x)); } } for (const c of list) { if (chosen.length >= n) break; if (!chosen.includes(c)) chosen.push(c); } return chosen; }
const focus = pickDiverse(evald.filter(isFocus).sort((a, b) => b.score - a.score), 3).sort((a, b) => b.score - a.score);

function whyWait(r) {
  if (r.cnt < 3) return '4H/1H/15m এর একটা এখনও align হয়নি';
  if (orReady && !r.orConfirmed) return r.orLive ? '15m candle close এর অপেক্ষা (OR break হচ্ছে)' : 'Opening range break এর অপেক্ষা';
  if (r.cramped) return 'সামনে PDH/PDL কাছে — RR কম';
  return 'Score 65 এর নিচে';
}
const watch = evald.filter(r => !focus.includes(r) && r.bias && r.cnt >= 2 && r.score >= 55).sort((a, b) => b.score - a.score).slice(0, 2);

function avoidReasons(r) {
  const o = [];
  if (r.cnt < 3) o.push('4H/1H/15m এক দিকে না — trend confirm নয়');
  if (r.er < 0.25) o.push(`Choppy (ER ${r.er.toFixed(2)}) — scalp এর জন্য খারাপ`);
  if (r.act < 0.7) o.push('Move কম — এখন volatility নেই');
  if (r.cramped) o.push('সামনে PDH/PDL খুব কাছে — RR কম');
  if (r.adrPct !== null && r.adrPct >= 110) o.push(`ADR ${r.adrPct}% — আজকের move প্রায় শেষ`);
  if (r.stretched) o.push(`RSI ${r.rsi.toFixed(0)} — ${r.bias === 'BUY' ? 'overbought' : 'oversold'}, উল্টো move ঝুঁকি`);
  if (r.extended) o.push('EMA50 থেকে অনেক দূরে — late entry ঝুঁকি');
  if (orReady && r.bias && !r.orConfirmed) o.push('Opening range break হয়নি');
  if (!o.length) o.push('Criteria পূরণ হয়নি');
  return o.slice(0, 2);
}
const avoid = evald.filter(r => !focus.includes(r) && !watch.includes(r)).sort((a, b) => a.score - b.score).slice(0, 3);

const medals = ['🥇', '🥈', '🥉'];
const bar = s => { const f = Math.max(0, Math.min(10, Math.round(s / 10))); return '▓'.repeat(f) + '░'.repeat(10 - f); };
const conf = s => s >= 80 ? '🔥 HIGH' : s >= 65 ? '✅ GOOD' : s >= 50 ? '🟡 MEDIUM' : '⚪ LOW';
const fmt = (r, v) => v.toFixed(r.kind === 'asset' ? r.dec : (r.pair.includes('JPY') ? 3 : 5));
const fl = r => (r.kind === 'asset' ? `${r.icon} ${r.name}` : `${flags[r.base]}${flags[r.quote]} ${r.pair}`);
const arrow = r => r.bias === 'BUY' ? '📈 BUY' : r.bias === 'SELL' ? '📉 SELL' : '➖';
const time = new Date().toLocaleString('en-GB', { timeZone: 'Asia/Dhaka', hour: '2-digit', minute: '2-digit' });
const scope = cfg.watchlist ? `${cfg.watchlist.length} item watchlist` : 'সব 28 pair + 4 asset';
const hasAsset = evald.some(r => r.kind === 'asset');

function render(compact) {
  const L = [];
  L.push(`🎯 ${cfg.session.toUpperCase()} · SCALP FOCUS`);
  L.push(`⏰ ${time} BDT · ${scope}`);
  if (nowSec - lastTs > 10800) L.push('🕒 Forex market বন্ধ — শেষ available data');
  if (closedAssets.length) L.push(`🕒 বন্ধ: ${closedAssets.join(', ')} (market closed)`);
  if (!orReady) L.push(cfg.orDone ? '⚠️ Opening range data নেই — শুধু trend ভিত্তিক' : `⏳ Opening range চলছে (${(cfg.startHour + 1) % 24}:00 এ শেষ) — breakout confirm হয়নি, trend ভিত্তিক focus`);
  if (skipped.length) L.push(`⚠️ ${skipped.length} টার data আসেনি — strength সামান্য অসম্পূর্ণ`);
  L.push('');
  L.push('━━━━━━━━━━━━━━━━━━━');
  L.push('✅ FOCUS');
  L.push('━━━━━━━━━━━━━━━━━━━');
  L.push('');
  if (!evald.length) L.push('Watchlist এর কোনো item এর data পাওয়া যায়নি — নাম চেক করো।');
  else if (!focus.length) L.push('এই মুহূর্তে কিছু পুরো criteria পূরণ করেনি — অপেক্ষা করা ভালো।');
  focus.forEach((r, i) => {
    L.push(`${medals[i]} ${fl(r)}  ${arrow(r)}`);
    L.push(`⭐ ${r.score}/100 ${bar(r.score)} · ${conf(r.score)}`);
    if (r.kind === 'asset') L.push(`📊 EMA থেকে দূরত্ব (ATR): 4H ${sg(r.d4)} · 1H ${sg(r.d1)} · 15m ${sg(r.d15)}`);
    else L.push(`📊 4H ${sg(r.d4)} · 1H ${sg(r.d1)} · 15m ${sg(r.d15)} (${r.base} vs ${r.quote})`);
    L.push(`🧹 ER ${r.er.toFixed(2)} — ${r.er >= 0.4 ? 'clean trend' : 'মোটামুটি trend'}`);
    if (orReady) L.push(`🚀 OR (${cfg.startHour}:00) ${r.bias === 'BUY' ? 'high ' + fmt(r, r.orHigh) + ' এর উপরে' : 'low ' + fmt(r, r.orLow) + ' এর নিচে'} 15m close ✅`);
    else L.push('⏳ OR চলছে — breakout confirm হয়নি');
    L.push(r.obstacle !== null ? `📍 সামনে ${r.bias === 'BUY' ? 'PDH' : 'PDL'} ${fmt(r, r.obstacle)} — ${r.roomATR.toFixed(1)} ATR room` : '📍 সামনে PDH/PDL এর বাধা নেই');
    L.push(`📏 ADR ${r.adrPct === null ? '—' : r.adrPct + '%'} · ⚡ Activity ${r.act.toFixed(1)}x`);
    if (r.stretched) L.push(`⚠️ RSI ${r.rsi.toFixed(0)} — ${r.bias === 'BUY' ? 'overbought, pullback' : 'oversold, bounce'} ঝুঁকি`);
    if (r.divAgainst) L.push('⚠️ RSI divergence উল্টো দিকে — reversal সতর্কতা');
    if (r.extended) L.push('⚠️ EMA50 থেকে অনেক দূরে — late entry ঝুঁকি');
    if (!compact) {
      L.push(`🧮 Trend ${r.A}/35 · Clean ${r.C}/20 · Activity ${r.D}/10 · Session ${r.E}/5 · OR ${r.F}/15 · Room ${r.G}/15${r.pen ? ' · Penalty -' + r.pen : ''}`);
      L.push(`🎯 3m/1m এ pullback/retest এ ${r.bias} খোঁজো · bias বাতিল: 15m close ${fmt(r, r.e50)} এর ${r.bias === 'BUY' ? 'নিচে' : 'উপরে'}`);
    }
    L.push('');
    L.push('──────────────────');
    L.push('');
  });
  if (watch.length) {
    L.push('👀 WATCH (setup তৈরি হচ্ছে)');
    for (const r of watch) L.push(`🟡 ${fl(r)} ${arrow(r)} · ${r.score} — ${whyWait(r)}`);
    L.push('');
  }
  if (avoid.length) {
    L.push('🚫 AVOID');
    for (const r of avoid) {
      L.push(`🔴 ${fl(r)} · ${r.score}`);
      for (const x of avoidReasons(r)) L.push(`➖ ${x}`);
    }
    L.push('');
  }
  L.push('🔥 80+ · ✅ 65-79 · 🟡 50-64 · ⚪ <50');
  if (hasAsset) L.push('ℹ️ Gold/Silver/Oil = futures data (GC=F, SI=F, CL=F) — MT5 spot এর সাথে price এ fark থাকবে, level chart এ মিলিয়ে নিও · Bitcoin ২৪/৭ চলে, OR কম নির্ভরযোগ্য');
  L.push('⚠️ Automated analysis (heuristic score, backtest করা না) — entry এর আগে chart এ নিজের confirmation নিও।');
  return L.join('\n').trim();
}

let text = render(false);
if (text.length > 3900) text = render(true);
return [{ json: { text } }];

const m = $input.first().json.message || {};
const text = (m.text || '').trim().toLowerCase();
if (!m.chat || String(m.chat.id) !== '5884335011') return [];
const words = text.split(' ');
