      data: { datasets: ds },
      options: {
        plugins: {
          title: { display: true, text: `${it.name} · 1m · ${it.bias} · ${it.score}/100 (BDT)`, font: { size: 20 } },
          legend: { position: 'top' }
        },
        scales: {
          x: { type: 'time', min: x0, max: xMax, time: { unit: 'minute', displayFormats: { minute: 'HH:mm', hour: 'HH:mm', day: 'HH:mm' } }, ticks: { source: 'auto', autoSkip: true, maxTicksLimit: 12, maxRotation: 0 }, grid },
          y: { stack: 'main', stackWeight: 3, position: 'right', min: yMin, max: yMax, ticks: { stepSize: step, includeBounds: false }, grid },
          yRsi: { stack: 'main', stackWeight: 1, position: 'right', min: 0, max: 110, ticks: { stepSize: 20, includeBounds: false }, grid, title: { display: true, text: 'RSI' } }
        }
      }
    }
  };

  out.push({ json: {
    body,
    caption: `${it.tag === 'GO' ? '🟢 GO' : '🟡 WAIT'} ${it.name} ${it.bias === 'BUY' ? '📈 BUY' : '📉 SELL'} · ${it.score}/100 · 1m` + (e200Out ? '\n⚠️ EMA 200 chart এর range এর বাইরে (দাম অনেক দূরে)' : '')
  } });
});
return out;
